package fr.minenorth.portes.command; import com.mojang.brigadier.CommandDispatcher; import fr.minenorth.portes.config.SystemeConfigFiles; import net.minecraft.commands.CommandSourceStack; import net.minecraft.commands.Commands; import net.minecraft.network.chat.Component; import net.minecraftforge.event.RegisterCommandsEvent; import net.minecraftforge.eventbus.api.SubscribeEvent; import net.minecraftforge.fml.common.Mod; @Mod.EventBusSubscriber public class DoorCommands{@SubscribeEvent public static void register(RegisterCommandsEvent e){e.getDispatcher().register(Commands.literal("portereload").requires(s->s.hasPermission(2)).executes(c->reload(c.getSource())));}private static int reload(CommandSourceStack s){int n=SystemeConfigFiles.reloadDoors(s.getServer());s.sendSystemMessage(Component.literal("Configuration des portes rechargée : "+n+" porte(s)."));return n<0?0:1;}}
